import re, json, urllib.request, time
from concurrent.futures import ThreadPoolExecutor
UA={'User-Agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/128.0 Safari/537.36'}
r=open('roster.html',encoding='utf8').read()
links=sorted(set(re.findall(r'/sports/spirit-squad/roster/([a-z0-9-]+)/([0-9]+)',r)))
def get(l):
    u=f'https://baylorbears.com/sports/spirit-squad/roster/{l[0]}/{l[1]}'
    for a in range(3):
        try:
            b=urllib.request.urlopen(urllib.request.Request(u,headers=UA),timeout=40).read().decode('utf8','ignore')
            og=re.search(r'property="og:image" content="([^"]+)"',b); alt=re.search(r'property="og:image:alt" content="([^"]+)"',b)
            t=re.search(r'<title>(.*?) - Spirit',b,re.S)
            m=re.search(r'images%2F(20[0-9]{2}%2F[0-9]+%2F[0-9]+%2F[^&"]+)',og.group(1)) if og else None
            return {'slug':l[0],'id':l[1],'name':t.group(1).strip() if t else None,'alt':alt.group(1) if alt else None,
                    'path':m.group(1).replace('%2F','/') if m else None,'og':og.group(1) if og else None}
        except Exception as e: err=str(e); time.sleep(2)
    return {'slug':l[0],'id':l[1],'error':err}
with ThreadPoolExecutor(4) as ex: res=list(ex.map(get,links))
json.dump(res,open('web_roster.json','w'),indent=1)
print('pages',len(res),'errors',sum('error' in x for x in res))
from collections import Counter
print('image folders:',Counter((x.get('path') or 'NONE').rsplit('/',1)[0] for x in res))
for x in res: print(f"{x['slug']:28} {x.get('path')}")
EOF

